    expect(validateSettings([])).toBe(null);
  });

  // 数组也是 object——但仍是合法载体形态，逐字段校验通过后返回 null
  // 端口类边界：0 / 负数 / 小数 / 超 65535
  const badPorts = [0, -1, 3.5, 65536, "80"].map((p) => ({ title: `port=${JSON.stringify(p)} 非法`, p }));
