    // C4: 中断重放四分支（成功/损坏 bak/无效 bak/update 失败），resumed=true。
    describe("C4: 中断重放四分支", () => {
      // 用例表必须是收集期静态量：it.each 的表在 beforeAll 之前就已求值。
      const badBakCases = [
        { raw: "{bad", expectMigrated: false },
